class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        g=[r[:] for r in grid]; n=0
        for i in range(len(g)):
            for j in range(len(g[0])):
                if g[i][j]=='1':
                    n+=1; st=[(i,j)]; g[i][j]='0'
                    while st:
                        a,b=st.pop()
                        for x,y in((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                            if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]=='1':
                                g[x][y]='0'; st.append((x,y))
        return n

class Solution:
    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        from collections import deque
        adj=[[] for _ in range(numCourses)]; ind=[0]*numCourses
        for a,b in prerequisites: adj[b].append(a); ind[a]+=1
        q=deque(i for i in range(numCourses) if ind[i]==0); seen=0
        while q:
            u=q.popleft(); seen+=1
            for v in adj[u]:
                ind[v]-=1
                if ind[v]==0: q.append(v)
        return seen==numCourses

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        dp=[0]+[amount+1]*amount
        for a in range(1,amount+1):
            for c in coins:
                if c<=a: dp[a]=min(dp[a],dp[a-c]+1)
        return dp[amount] if dp[amount]<=amount else -1

